use atlas_sqlcipher_proof::Vault;
#[test]fn encrypted_draft_is_durable_and_preserves_search(){let p=std::env::temp_dir().join(format!("atlas-draft-protected-{}",std::process::id()));let mut v=Vault::create(&p,"password").unwrap();v.put_note("note","before","olduniqueword").unwrap();v.save_note_draft_guarded("note","after","newuniqueword",||Ok(())).unwrap();assert_eq!(v.search("olduniqueword").unwrap(),vec!["note"]);assert!(v.search("newuniqueword").unwrap().is_empty());drop(v);let mut v=Vault::open(&p,"password").unwrap();assert_eq!(v.get_note_draft("note").unwrap(),Some(("after".into(),"newuniqueword".into())));assert!(!v.clear_note_draft_guarded("note","after","different",||Ok(())).unwrap());assert!(v.clear_note_draft_guarded("note","after","newuniqueword",||Ok(())).unwrap());drop(v);std::fs::remove_file(p).unwrap();}
#[test]fn conversion_refuses_unrecovered_encrypted_draft(){let root=std::env::temp_dir().join(format!("atlas-draft-convert-{}",std::process::id()));let mut v=Vault::create(&root,"password").unwrap();v.put_note("note","title","old").unwrap();v.save_note_draft_guarded("note","title","new",||Ok(())).unwrap();let dest=root.with_extension("out");assert!(v.export_plain(&dest).is_err());assert!(!dest.exists());assert_eq!(v.get_note_draft("note").unwrap().unwrap().1,"new");assert_eq!(v.recover_note_drafts_guarded(||Ok(())).unwrap(),1);assert_eq!(v.search("new").unwrap(),vec!["note"]);drop(v);std::fs::remove_file(root).unwrap();}
#[test]fn conversion_refuses_unrecovered_plain_draft(){let root=std::env::temp_dir().join(format!("atlas-draft-plain-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"title".into(),"old".into()];let id=atlas_native_storage_contract::execute(&args).unwrap()["id"].as_str().unwrap().to_owned();atlas_native_storage_contract::save_note_draft(&root,&id,"title","new").unwrap();let dest=root.with_extension("vault");assert!(Vault::import_plain(&root,&dest,"password").is_err());assert!(!dest.exists());assert_eq!(atlas_native_storage_contract::get_note_draft(&root,&id).unwrap().unwrap().1,"new");std::fs::remove_dir_all(root).unwrap();}
#[test]fn trashed_encrypted_draft_survives_copy_and_undo(){let p=std::env::temp_dir().join(format!("atlas-draft-vault-trash-{}",std::process::id()));let copy=p.with_extension("copy");let mut v=Vault::create(&p,"password").unwrap();v.put_note("note","old title","oldword").unwrap();v.save_note_draft_guarded("note","new title","restoreduniqueword",||Ok(())).unwrap();v.trash("note",1).unwrap();drop(v);std::fs::copy(&p,&copy).unwrap();for path in [&p,&copy]{let mut v=Vault::open(path,"password").unwrap();assert!(v.get_note_draft("note").unwrap().is_some());v.restore("note").unwrap();assert_eq!(v.get_note("note").unwrap(),"restoreduniqueword");assert_eq!(v.search("restoreduniqueword").unwrap(),vec!["note"]);assert!(v.get_note_draft("note").unwrap().is_none());}std::fs::remove_file(p).unwrap();std::fs::remove_file(copy).unwrap();}
#[test]fn trashed_draft_survives_password_conversion_both_ways(){let root=std::env::temp_dir().join(format!("atlas-draft-convert-trash-{}",uuid::Uuid::new_v4()));atlas_native_storage_contract::create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"old".into(),"oldword".into()];let id=atlas_native_storage_contract::execute(&args).unwrap()["id"].as_str().unwrap().to_owned();atlas_native_storage_contract::save_note_draft(&root,&id,"new","restoreduniqueword").unwrap();atlas_native_storage_contract::delete_objects(&root,&[id.clone()]).unwrap();let vault_path=root.with_extension("vault");let v=Vault::import_plain(&root,&vault_path,"password").unwrap();v.set_workspace_name_guarded("test",||Ok(())).unwrap();assert_eq!(v.get_note_draft(&id).unwrap().unwrap().1,"restoreduniqueword");let dest=root.with_extension("plain");v.export_plain(&dest).unwrap();drop(v);atlas_native_storage_contract::restore_objects(&dest,&[id.clone()]).unwrap();assert!(atlas_native_storage_contract::get_note_draft(&dest,&id).unwrap().is_none());let db=rusqlite::Connection::open(dest.join("atlas.sqlite3")).unwrap();let n:i64=db.query_row("SELECT count(*) FROM search_index WHERE search_index MATCH 'restoreduniqueword'",[],|r|r.get(0)).unwrap();assert_eq!(n,1);drop(db);std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(dest).unwrap();std::fs::remove_file(vault_path).unwrap();}
